import React, { useState } from "react";

const PublicationsSection = () => (
  <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
      }}
    >
      <h1
        style={{
          fontSize: "32px",
          fontWeight: "bold",
          color: "#003865",
          margin: 0,
        }}
      >
        Publications & Alertes
      </h1>
      <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
        <div style={{ position: "relative" }}>
          <input
            type="text"
            placeholder="Rechercher..."
            style={{
              paddingLeft: "40px",
              paddingRight: "16px",
              paddingTop: "8px",
              paddingBottom: "8px",
              border: "1px solid #d9d9d9",
              borderRadius: "8px",
              fontSize: "14px",
              outline: "none",
            }}
          />
          <span
            style={{
              position: "absolute",
              left: "12px",
              top: "50%",
              transform: "translateY(-50%)",
              color: "#999",
            }}
          >
            🔍
          </span>
        </div>
        <button
          style={{
            backgroundColor: "#f5f5f5",
            border: "none",
            padding: "8px",
            borderRadius: "8px",
            cursor: "pointer",
          }}
        >
          <span>🔽</span>
        </button>
      </div>
    </div>

    <div
      style={{
        backgroundColor: "#fff",
        borderRadius: "12px",
        boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
      }}
    >
      <div
        style={{
          padding: "24px",
          borderBottom: "1px solid #d9d9d9",
        }}
      >
        <h2
          style={{
            fontSize: "20px",
            fontWeight: "600",
            color: "#003865",
            margin: 0,
          }}
        >
          Alertes récentes
        </h2>
      </div>
      <div>
        {alertes.map((alerte, index) => (
          <div
            key={alerte.id}
            style={{
              padding: "24px",
              borderBottom:
                index < alertes.length - 1 ? "1px solid #d9d9d9" : "none",
              transition: "background-color 0.2s",
            }}
            onMouseOver={(e) =>
              (e.currentTarget.style.backgroundColor = "#f9f9f9")
            }
            onMouseOut={(e) =>
              (e.currentTarget.style.backgroundColor = "transparent")
            }
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "flex-start",
              }}
            >
              <div style={{ flex: 1 }}>
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "8px",
                    marginBottom: "8px",
